/**
 * Stand-in for SvelteKit's `$env/dynamic/private` under Vitest.
 *
 * The real module is generated by SvelteKit's build, so anything importing it
 * (route handlers, mostly) is unresolvable in a plain unit test. Aliased in
 * `vitest.config.ts`. Tests set the keys they need and clear them afterwards:
 *
 *     import { env } from '$env/dynamic/private';
 *     beforeEach(() => { for (const k of Object.keys(env)) delete env[k]; });
 */
export const env: Record<string, string | undefined> = {};
